    st.push(
      env.DB.prepare("DELETE FROM notification_dedup WHERE created_at<?1 AND scope IN (SELECT value FROM json_each(?2))").bind(
        Date.now() - NF_TTL,
        JSON.stringify(
          Array.from(
            new Set(
              once.map(function (r) {
                return r.scope;
              }),
            ),
          ),
        ),
      ),
    );
